@interface FMFormatFileManager : NSFileManager
@property(nonatomic,strong) NSURL *applicationSupport;
@property(nonatomic,copy) NSString *failSourcePath,*failSourceParent,*failRestoreDestination;
@property(nonatomic) BOOL throwFailure;
@end
@implementation FMFormatFileManager
- (NSArray<NSURL *> *)URLsForDirectory:(NSSearchPathDirectory)directory inDomains:(NSSearchPathDomainMask)domains {
    if(directory==NSApplicationSupportDirectory)return self.applicationSupport?@[self.applicationSupport]:@[];
    return [super URLsForDirectory:directory inDomains:domains];
}
- (BOOL)moveItemAtURL:(NSURL *)source toURL:(NSURL *)destination error:(NSError **)error {
    BOOL commit=[source.path isEqual:self.failSourcePath] || [source.URLByDeletingLastPathComponent.path isEqual:self.failSourceParent];
    BOOL restore=[source.URLByDeletingLastPathComponent.lastPathComponent hasPrefix:@".FMJSReplacement-"] && [destination.path isEqual:self.failRestoreDestination];
    if(commit || restore){
        if(self.throwFailure)@throw [NSException exceptionWithName:@"AuthoredSaveException" reason:@"Injected file move failure" userInfo:nil];
        if(error)*error=[NSError errorWithDomain:NSCocoaErrorDomain code:NSFileWriteNoPermissionError userInfo:nil];return NO;
    }
    return [super moveItemAtURL:source toURL:destination error:error];
}
@end

static NSArray *NativeExtensions(void) {
    return @[@"mp3",@"flac",@"m4a",@"wav",@"ogg",@"opus",@"aac",@"aif",@"aiff",@"aifc",@"caf",@"mp4",@"ape",@"wv",@"mpc",@"tta",@"spx",@"dsf",@"dff"];
}
static BOOL EqualFile(NSURL *URL,NSData *data) {return [[NSData dataWithContentsOfURL:URL] isEqual:data];}
static BOOL Exists(NSURL *URL) {return [NSFileManager.defaultManager fileExistsAtPath:URL.path];}
static NSURL *MakeDirectory(NSURL *root,NSString *name) {
    NSURL *directory=[root URLByAppendingPathComponent:name isDirectory:YES];NSError *error=nil;
    if(![NSFileManager.defaultManager createDirectoryAtURL:directory withIntermediateDirectories:YES attributes:nil error:&error])
        @throw [NSException exceptionWithName:@"FixtureSetup" reason:error.localizedDescription userInfo:nil];
    return directory;
}
static NSURL *Write(NSURL *directory,NSString *name,NSData *bytes) {
    NSURL *URL=[directory URLByAppendingPathComponent:name];NSError *error=nil;
    if(![bytes writeToURL:URL options:NSDataWritingAtomic error:&error])@throw [NSException exceptionWithName:@"FixtureSetup" reason:error.localizedDescription userInfo:nil];
    return URL;
}
static NSURL *Incoming(NSURL *directory,NSString *identifier,NSString *extension,NSData *bytes) {
    NSURL *typed=Write(directory,[NSUUID.UUID.UUIDString stringByAppendingPathExtension:extension],bytes);NSError *error=nil;
    if(!FMDownloadIntegrationRegisterFileForTesting(typed,[@"tx:" stringByAppendingString:identifier],extension,&error))
        @throw [NSException exceptionWithName:@"FixtureRegistration" reason:error.localizedDescription userInfo:nil];
    // The original delegate first adopts the file into an anonymous temporary
    // path. The final-save ownership must survive that real filesystem rename.
    NSURL *anonymous=[directory URLByAppendingPathComponent:[NSUUID.UUID.UUIDString stringByAppendingPathExtension:@"tmp"]];
    if(![NSFileManager.defaultManager moveItemAtURL:typed toURL:anonymous error:&error])
        @throw [NSException exceptionWithName:@"FixtureAdoption" reason:error.localizedDescription userInfo:nil];
    return anonymous;
}
static NSURL *Destination(NSURL *downloads,NSString *identifier,NSString *extension) {
    return [downloads URLByAppendingPathComponent:[[ @"qq_" stringByAppendingString:identifier] stringByAppendingPathExtension:extension]];
}
static BOOL RegularNonempty(NSURL *URL) {struct stat value;return lstat(URL.fileSystemRepresentation,&value)==0 && S_ISREG(value.st_mode) && value.st_size>0;}
static NSURL *NativeLookup(NSURL *downloads,NSURL *assets,NSString *identifier) {
    NSURL *MP3=Destination(downloads,identifier,@"mp3");if(RegularNonempty(MP3))return MP3;
    NSURL *CAF=[assets URLByAppendingPathComponent:[NSString stringWithFormat:@"qq_%@_playback.caf",identifier]];
    if(RegularNonempty(CAF))return CAF;
    for(NSString *extension in NativeExtensions()){NSURL *file=Destination(downloads,identifier,extension);if(RegularNonempty(file))return file;}return nil;
}
static BOOL DecodeToEnd(NSURL *file) {
    AVURLAsset *asset=[AVURLAsset URLAssetWithURL:file options:nil];__block BOOL loaded=NO;
    [asset loadValuesAsynchronouslyForKeys:@[@"tracks",@"duration",@"playable"] completionHandler:^{dispatch_async(dispatch_get_main_queue(),^{loaded=YES;});}];
    if(!Wait(^BOOL{return loaded;},8)){[asset cancelLoading];return NO;}
    for(NSString *key in @[@"tracks",@"duration",@"playable"])if([asset statusOfValueForKey:key error:nil]!=AVKeyValueStatusLoaded)return NO;
    AVAssetTrack *track=[asset tracksWithMediaType:AVMediaTypeAudio].firstObject;
    double duration=CMTimeGetSeconds(asset.duration);if(!track || !asset.playable || !isfinite(duration) || duration<=0)return NO;
    NSError *error=nil;AVAssetReader *reader=[[AVAssetReader alloc] initWithAsset:asset error:&error];if(!reader)return NO;
    AVAssetReaderTrackOutput *output=[[AVAssetReaderTrackOutput alloc] initWithTrack:track outputSettings:@{AVFormatIDKey:@(kAudioFormatLinearPCM),AVLinearPCMBitDepthKey:@16,AVLinearPCMIsFloatKey:@NO,AVLinearPCMIsBigEndianKey:@NO,AVLinearPCMIsNonInterleaved:@NO}];
    if(![reader canAddOutput:output])return NO;[reader addOutput:output];if(![reader startReading])return NO;
    NSUInteger samples=0;for(;;){CMSampleBufferRef buffer=[output copyNextSampleBuffer];if(!buffer)break;samples+=(NSUInteger)MAX(0,CMSampleBufferGetNumSamples(buffer));CFRelease(buffer);}
    return samples>0 && reader.status==AVAssetReaderStatusCompleted;
}
static NSArray<NSURL *> *Backups(NSURL *downloads) {
    NSMutableArray *result=NSMutableArray.array;
    for(NSURL *URL in [NSFileManager.defaultManager contentsOfDirectoryAtURL:downloads includingPropertiesForKeys:nil options:0 error:nil])
        if([URL.lastPathComponent hasPrefix:@".FMJSReplacement-"])[result addObject:URL];return result;
}

// Model the confirmed original save branch: YES registers the downloaded track,
// NO preserves its error, and didComplete(nil) does not override a save failure.
@interface FMFormatHostDelegate : NSObject <NSURLSessionDownloadDelegate>
@property(nonatomic,strong) FMFormatFileManager *manager;
@property(nonatomic,strong) NSURL *downloads,*adopted,*savedFile;
@property(nonatomic,copy) NSString *identifier;
@property(nonatomic,strong) NSError *saveError,*transportError;
@property(nonatomic) NSUInteger registered,finishes,completions;
@end
@implementation FMFormatHostDelegate
- (void)URLSession:(NSURLSession *)session downloadTask:(NSURLSessionDownloadTask *)task didWriteData:(int64_t)bytes totalBytesWritten:(int64_t)total totalBytesExpectedToWrite:(int64_t)expected {}
